function App() {
  const subscribe = (cb) => {
    window.addEventListener('online', cb);
    window.addEventListener('offline', cb);
    return () => {
      window.removeEventListener('online', cb);
      window.removeEventListener('offline', cb);
    };
  };
  const getSnapshot = () => navigator.onLine;
  const isOnline = useSyncExternalStore(subscribe, getSnapshot);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h2>{isOnline ? '🟢 Online' : '🔴 Offline'}</h2>
      <p>Toggle your network to see this update.</p>
    </div>
  );
}

function App() {
  const store = (function createStore() {
    let state = { count: 0 };
    const listeners = new Set();
    return {
      getState: () => state,
      increment: () => {
        state = { count: state.count + 1 }; // new ref on real change
        listeners.forEach(l => l());
      },
      subscribe: (l) => { listeners.add(l); return () => listeners.delete(l); }
    };
  });
  const [ref] = useState(store);
  const state = useSyncExternalStore(ref.subscribe, ref.getState);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h2>Count: {state.count}</h2>
      <button onClick={ref.increment}>+1</button>
    </div>
  );
}

