function App() {
  const make = () => {
    let state = { theme: 'light' };
    const listeners = new Set();
    return {
      getState: () => state,
      subscribe: (l) => { listeners.add(l); return () => listeners.delete(l); },
      toggleTheme: () => {
        state = { theme: state.theme === 'light' ? 'dark' : 'light' };
        listeners.forEach(l => l());
      }
    };
  };
  const [store] = useState(make);
  const state = useSyncExternalStore(store.subscribe, store.getState);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16, background: state.theme === 'dark' ? '#222' : '#fff', color: state.theme === 'dark' ? '#fff' : '#000' }}>
      <h2>Theme: {state.theme}</h2>
      <button onClick={store.toggleTheme}>Toggle</button>
    </div>
  );
}

