function App() {
  const [store] = useState(() => {
    let state = { count: 0 };
    const listeners = new Set();
    return {
      increment: () => { state = { count: state.count + 1 }; listeners.forEach(l => l()); },
      subscribe: (l) => { listeners.add(l); return () => listeners.delete(l); },
      getSnapshot: () => state // stable ref; new only on real change
    };
  });
  const state = useSyncExternalStore(store.subscribe, store.getSnapshot);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h2>Count: {state.count}</h2>
      <button onClick={store.increment}>+1</button>
    </div>
  );
}

function App() {
  function createStore(initial) {
    let state = initial;
    const listeners = new Set();
    return {
      getState: () => state, // stable ref until setState replaces it
      setState: (fn) => { state = fn(state); listeners.forEach(l => l()); },
      subscribe: (l) => { listeners.add(l); return () => listeners.delete(l); }
    };
  }
  function useStore(store) {
    return useSyncExternalStore(store.subscribe, store.getState);
  }
  const [store] = useState(() => createStore({ count: 0 }));
  const state = useStore(store);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h2>Count: {state.count}</h2>
      <button onClick={() => store.setState(s => ({ count: s.count + 1 }))}>+1</button>
    </div>
  );
}
